#!/usr/bin/env python3
"""Validate the text-audit package with only the Python standard library."""

from __future__ import annotations

import re
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
VERSION_RE = re.compile(r"^\s*version:\s*([0-9]+\.[0-9]+\.[0-9]+)\s*$", re.M)

# Every relative path SKILL.md cites in Markdown-link form, e.g. [`references/reader-prompt.md`]
# (references/reader-prompt.md) or a bare `references/reader-prompt.md` code span. Only paths under
# this skill's own tree are checked; a path belonging to the project under audit is not on disk here.
LINK_RE = re.compile(r"\(((?:references|evals)/[^)\s]+\.md)\)")


def fail(message: str) -> None:
    raise AssertionError(message)


def read(relative: Path | str) -> str:
    path = ROOT / relative
    if not path.is_file():
        fail(f"missing required file: {relative}")
    return path.read_text(encoding="utf-8")


def version_from(text: str, source: str) -> str:
    match = VERSION_RE.search(text)
    if not match:
        fail(f"{source} carries no semantic version")
    return match.group(1)


def validate_package() -> str:
    skill = read("SKILL.md")
    readme = read("README.md")

    version = version_from(skill, "SKILL.md")
    if version not in readme:
        fail("README.md and SKILL.md disagree on the version")

    for relative in sorted(set(LINK_RE.findall(skill))):
        path = ROOT / relative
        if not path.is_file():
            fail(f"SKILL.md names {relative}, which is not on disk")

    workflow = read(".github/workflows/validate.yml")
    if "scripts/validate.py" not in workflow:
        fail("CI does not run this validator")

    return version


def main() -> int:
    try:
        version = validate_package()
    except (AssertionError, OSError) as exc:
        print(f"text-audit: FAIL — {exc}", file=sys.stderr)
        return 1
    print(f"text-audit: OK — {version}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

